'use strict';
(async()=>{
 const status=document.getElementById('connectionStatus');let data=window.TRIP_DATA;
 if(window.TRIP_CONFIG.appsScriptUrl){status.textContent='여행지 목록을 불러오는 중…';try{const result=await window.tripApi('/api/catalog');if(!Array.isArray(result.cities)||!result.cities.length)throw Error('도시 없음');data=result.cities.map(c=>({...data.find(x=>x.id===c.id),...c}));status.textContent=''}catch{status.textContent='연결이 지연되어 기본 장소 목록을 표시합니다. 개인 저장과 추천은 연결 후 이용할 수 있어요.'}}else status.textContent='공유 저장소 연결 전 · 기본 일정과 사진 저장을 사용할 수 있어요.';
 const safeId=/^[a-z0-9_-]+$/;data=data.filter(c=>safeId.test(c.id)&&c.places?.length&&Object.keys(c.areas||{}).length);if(!data.length){status.textContent='여행지 설정을 확인해주세요.';return}
 const id=new URLSearchParams(location.search).get('city');const city=window.TRIP_CITY=data.find(c=>c.id===id)||data[0];document.title='Trip Days · '+city.name;document.documentElement.dataset.tripSlug='trip-days-'+city.id;document.documentElement.style.setProperty('--blue',/^#[a-f0-9]{6}$/i.test(city.color)?city.color:'#303e9e');
 const select=document.getElementById('citySelect'),nav=document.getElementById('cityNav');for(const c of data){select.add(new Option(c.name,c.id));const a=document.createElement('a');a.textContent=c.name;a.href='?city='+encodeURIComponent(c.id);if(c.id===city.id)a.setAttribute('aria-current','page');nav.append(a)}select.value=city.id;select.onchange=()=>location.search='?city='+encodeURIComponent(select.value);
 for(let n=1;n<=city.maxDays;n++)document.getElementById('days').add(new Option(n===1?'당일 여행':`${n-1}박 ${n}일`,n,false,n===city.defaultDays));for(const [key,label]of Object.entries(city.areas))document.getElementById('area').add(new Option(label,key,false,key===city.defaultArea));
 document.getElementById('cityEyebrow').textContent=city.id.toUpperCase()+' / '+city.country;document.getElementById('cityHeadline').textContent='나만의 '+city.name+'.';document.getElementById('cityPhotoCaption').textContent=city.name+', 느긋하게 즐기기';const photo=document.getElementById('cityPhoto');photo.src=city.photo||'assets/osaka.jpg';photo.alt=city.name+' 풍경';if(!city.photo)photo.closest('.photo').hidden=true;
 document.querySelector('#sightsTab span').textContent=city.places.filter(p=>p.type==='sight').length;document.querySelector('#foodTab span').textContent=city.places.filter(p=>p.type==='food'&&!p.tamnik).length;const count=city.places.filter(p=>p.tamnik).length;document.querySelector('#tamnikTab span').textContent=count;document.getElementById('tamnikTab').hidden=!count;
 for(const file of ['app.js','user-places.js','itinerary-export.js'])await new Promise((resolve,reject)=>{const s=document.createElement('script');s.src=file;s.onload=resolve;s.onerror=reject;document.body.append(s)});
})();
